#!/usr/bin/env bash
# Generated by `verdant-studio publish` from studio/src/Studio/Ops.lex.tex. Do not edit.
# The one Lean export of the certified command. operate's propose-command and refresh both run it,
# and the studio check runs propose-command end to end, so a change that breaks it fails there.
set -euo pipefail
ll="$1"
log="$2"
(cd studio && "$ll" lock && "$ll" check && "$ll" production build --request production-request.json) > "$log" 2>&1
rm -rf certified
cp -r studio/.lexlean/production/*/ certified
rm -f certified/packages/rust-std/verdant_studio/Cargo.lock
"$ll" production verify-artifact certified
